import {newsEvidence,mapFallbackLocation} from './observatorio-news-geo.mjs';
export function initWarReports({db,map,esc,date,addEvidence,readNews,render}){
 let rows=[],info=null,error=false,loading=false,reviews=new Map(),admin=false,authId=null;
 const context=document.getElementById('map-context');
 async function load(){if(loading)return;loading=true;render();try{const r=await fetch('/.netlify/functions/war-reports',{signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error();const data=await r.json();if(!Array.isArray(data.articles))throw Error();const result=await db?.from('atlas_dev_war_reviews').select('*').limit(1000);reviews=new Map((result?.error?[]:result?.data||[]).map(r=>[r.report_id,r]));rows=data.articles.map(a=>{const e=newsEvidence(a),place=mapFallbackLocation(a.title);return {...e,reportId:a.id,location:place,coordinates:place?.coordinates||null,verification:reviews.get(a.id)||null};});info=data;error=false;}catch{error=true;}finally{loading=false;render();}}
 function choose(e){if(e.coordinates)map.setView([e.coordinates[1],e.coordinates[0]],5);const review=reviews.get(e.reportId);context.innerHTML=`<span class="eyebrow">${review?'CONFIRMADO · REVISIÓN EDITORIAL':'REPORTE PRELIMINAR'}</span><h2>${esc(e.title)}</h2><p><strong>${esc(e.source)}</strong> · vía Google News RSS</p><dl><dt>Publicación de la noticia</dt><dd>${esc(date(e.date))}</dd><dt>Fecha del hecho</dt><dd>${review?esc(review.event_date):'No determinada: la fecha del titular no confirma cuándo ocurrió.'}</dd><dt>Ubicación</dt><dd>${e.location?esc(e.location.label)+' · referencia aproximada del titular; no coordenadas verificadas del ataque.':'Sin ubicación suficientemente clara; disponible en la lista.'}</dd></dl>${review?`<p>${esc(review.note)}</p><p>Revisado ${esc(date(review.reviewed_at))}</p><p><a href="${esc(review.evidence_one)}" target="_blank" rel="noopener noreferrer">Fuente de respaldo 1 ↗</a> · <a href="${esc(review.evidence_two)}" target="_blank" rel="noopener noreferrer">Fuente de respaldo 2 ↗</a></p>`:'<p class="map-note">Reporte de prensa sin corroboración editorial registrada. La coincidencia entre titulares no confirma el hecho.</p>'}<p><a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">Abrir publicación ↗</a></p><div class="map-context-actions"><button id="war-read">Leer síntesis</button><button id="war-save">Seguir esta historia</button></div>${admin?review?'<button id="war-revoke">Retirar confirmación</button>':`<details><summary>Revisión administrativa</summary><form id="war-review"><p>Confirma solo tras revisar que dos fuentes independientes respaldan el mismo hecho. Los enlaces por sí solos no prueban independencia.</p><label>Fecha del hecho<input name="event_date" type="date" required max="${new Date().toISOString().slice(0,10)}"></label><label>Primera fuente<input name="evidence_one" type="url" required placeholder="https://…"></label><label>Segunda fuente independiente<input name="evidence_two" type="url" required placeholder="https://…"></label><label>Qué se confirmó y con qué límites<textarea name="note" required minlength="40" maxlength="2000"></textarea></label><button>Registrar confirmación</button><p id="war-review-status" role="status"></p></form></details>`:''}`;
 context.querySelector('#war-read').onclick=()=>readNews(e);context.querySelector('#war-save').onclick=()=>addEvidence({...e,detail:review?'Confirmación editorial: '+review.note:'Reporte preliminar. Fecha del hecho sin determinar; ubicación aproximada.'});
 const form=context.querySelector('#war-review');if(form)form.onsubmit=async ev=>{ev.preventDefault();const b=form.querySelector('button');b.disabled=true;const {error}=await db.from('atlas_dev_war_reviews').insert({report_id:e.reportId,...Object.fromEntries(new FormData(form))});if(error){context.querySelector('#war-review-status').textContent='No se pudo confirmar. Revisa fechas, fuentes distintas y permisos.';b.disabled=false;}else {await load();choose(rows.find(r=>r.id===e.id)||e);}};
 const revoke=context.querySelector('#war-revoke');if(revoke)revoke.onclick=async()=>{revoke.disabled=true;const {error}=await db.from('atlas_dev_war_reviews').delete().eq('report_id',e.reportId);if(error){revoke.textContent='No se pudo retirar; reintentar';revoke.disabled=false;}else{await load();choose(e);}};
 if(matchMedia('(max-width:900px)').matches)context.scrollIntoView({behavior:'smooth'});
 }
 async function auth(session){const uid=session?.user?.id||null;if(uid===authId)return;authId=uid;admin=false;context.innerHTML='';if(session?.user){const {data,error}=await db.rpc('atlas_dev_poll_admin');if(authId===uid)admin=!error&&data===true;}render();}
 db?.auth.getSession().then(({data})=>auth(data.session));db?.auth.onAuthStateChange((_event,s)=>setTimeout(()=>auth(s),0));
 setInterval(()=>{if(!document.hidden)load()},300000);
 return {load,choose,get rows(){return rows},get info(){return info},get error(){return error},get loading(){return loading}};
}
